using DriveOS.Modules.CurriculumPedagogy.Application.Readiness;using DriveOS.Modules.CurriculumPedagogy.Domain.PedagogicalReviews;using DriveOS.Modules.CurriculumPedagogy.Domain.RemediationPlans;using DriveOS.Modules.CurriculumPedagogy.Domain.TrainingPaths;using DriveOS.SharedKernel.Identifiers;using Microsoft.EntityFrameworkCore;
namespace DriveOS.Modules.CurriculumPedagogy.Infrastructure.Read;
internal sealed class PedagogicalReadinessReadService(Persistence.CurriculumPedagogyDbContext db):IPedagogicalReadinessReadService{public async Task<PedagogicalReadinessCheckResponse?> GetAsync(OrganizationId org,TrainingPathId pathId,CancellationToken ct=default){var path=await db.TrainingPaths.AsNoTracking().SingleOrDefaultAsync(x=>x.OrganizationId==org&&x.Id==pathId,ct);if(path is null)return null;var curricula=await db.Curricula.AsNoTracking().Where(x=>x.OrganizationId==org).Include(x=>x.Versions).ThenInclude(x=>x.Modules).ThenInclude(x=>x.Competencies).ToListAsync(ct);var version=curricula.SelectMany(x=>x.Versions).SingleOrDefault(x=>x.Id==path.CurriculumVersionId);if(version is null)return null;var required=version.Modules.SelectMany(x=>x.Competencies).Where(x=>x.IsRequired).Select(x=>x.Id).ToHashSet();var assessed=await db.CompetencyRecords.AsNoTracking().Where(x=>x.OrganizationId==org&&x.TrainingPathId==pathId).Select(x=>x.CompetencyId).ToListAsync(ct);int assessedRequired=assessed.Count(required.Contains);int openRemediation=await db.RemediationPlans.AsNoTracking().CountAsync(x=>x.OrganizationId==org&&x.TrainingPathId==pathId&&(x.Status==RemediationPlanStatus.Draft||x.Status==RemediationPlanStatus.Active),ct);bool hasReview=await db.PedagogicalReviews.AsNoTracking().AnyAsync(x=>x.OrganizationId==org&&x.TrainingPathId==pathId&&x.Status==PedagogicalReviewStatus.Completed,ct);var blockers=new List<string>();if(path.Status is not TrainingPathStatus.Active and not TrainingPathStatus.Suspended)blockers.Add("TrainingPathNotActive");if(required.Count>assessedRequired)blockers.Add("RequiredCompetenciesNotAssessed");if(openRemediation>0)blockers.Add("OpenRemediationPlan");if(!hasReview)blockers.Add("NoCompletedPedagogicalReview");var latest=await db.PedagogicalReadinessDecisions.AsNoTracking().Where(x=>x.OrganizationId==org&&x.TrainingPathId==pathId).OrderByDescending(x=>x.DecidedAtUtc).Select(x=>new PedagogicalReadinessDecisionResponse(x.Id.Value,x.Decision.ToString(),x.Rationale,x.Conditions,x.ReviewerId.Value,x.DecidedAtUtc)).FirstOrDefaultAsync(ct);decimal coverage=required.Count==0?100m:Math.Round((decimal)assessedRequired*100m/required.Count,2);string recommendation=blockers.Count==0?"EligibleForHumanDecision":"Blocked";return new PedagogicalReadinessCheckResponse(path.Id.Value,path.StudentId.Value,path.Status.ToString(),required.Count,assessedRequired,coverage,openRemediation,hasReview,recommendation,blockers,latest);}}
